string png=Convert.ToBase64String(System.Security.Cryptography.RandomNumberGenerator.GetBytes(1_000_000));var imageDoc=saved.Snapshot();imageDoc.PixelBasePng=png;var histories=new List<HistorySnapshot>();long baseline=0;var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<40;i++){imageDoc.Annotations[0].Text="Edit "+i;baseline+=imageDoc.Serialize().Length*2L;histories.Add(HistorySnapshot.Capture(imageDoc));}watch.Stop();long retained=HistorySnapshot.RetainedBytes(histories);Check(retained<baseline/15,"History uses under1/15 repeated JSON storage for40 image/text edits");Check(histories.All(h=>ReferenceEquals(h.Blobs.Single(),png)),"History shares immutable original image string");Check(histories[17].Restore().PixelBasePng==png&&histories[17].Restore().Annotations[0].Text=="Edit 17","Compressed history restores exact source and text");Console.WriteLine($"HISTORY_BASELINE_BYTES={baseline} HISTORY_RETAINED_BYTES={retained} CAPTURE40_MS={watch.Elapsed.TotalMilliseconds:F2}");var cancel=new EditorSession(imageDoc);string checkpoint=imageDoc.Serialize();cancel.Begin();cancel.Document.Annotations[0].Text="cancel";cancel.Cancel();Check(cancel.Document.Serialize()==checkpoint,"Cancel restores lossless snapshot");try{cancel.Change(d=>{d.Annotations.Clear();throw new ArgumentException();});}catch(ArgumentException){}Check(cancel.Document.Serialize()==checkpoint&&!cancel.CanUndo,"Failed transaction rolls back without history");
const int w=640,h=360;var pixels=Enumerable.Repeat((byte)255,w*h*4).ToArray();void Line(int x,int y,int width,int height){for(int yy=y;yy<y+height;yy++)for(int xx=x;xx<x+width;xx++){int p=(yy*w+xx)*4;pixels[p]=pixels[p+1]=pixels[p+2]=80;}}foreach(int y in new[]{50,120,190,260})Line(40,y,500,1);foreach(int x in new[]{40,200,400,539})Line(x,50,1,211);var scan=UiReconstruction.Refine(new([],false),pixels,w,h,new(10,20,w,h));Check(scan.Elements.Any(e=>e.SemanticRole=="Table"&&e.KeepImage),"Intersecting grid detected as table retained losslessly");var flat=Enumerable.Repeat((byte)255,w*h*4).ToArray();var first=new ScanElement{Bounds=new(10,10,80,20),Text="A",Confidence=.8};var duplicate=new ScanElement{Bounds=first.Bounds,Text="A",Confidence=.9,UiSourceId="uia"};var second=new ScanElement{Bounds=new(120,10,80,20),Text="B",Colors=new("#FFFFFF","#FFFFFF","#000000",.3)};var refined=UiReconstruction.Refine(new([first,duplicate,second],false),flat,w,h,new(0,0,w,h));Check(refined.Elements.Count==2&&refined.Elements.Contains(duplicate),"UI/OCR duplicate resolved in favor of UI match");Check(duplicate.LayoutGroup!=null&&duplicate.LayoutGroup==second.LayoutGroup&&second.KeepImage,"Aligned row grouped, complex background retained");
